package dev.kelmagic.artifact;
import dev.kelmagic.*;
import dev.kelmagic.server.*;
import java.util.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.level.*;
import net.minecraft.world.damagesource.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.projectile.Projectile;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.*;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.*;
import net.neoforged.neoforge.event.entity.ProjectileImpactEvent;
import net.neoforged.neoforge.event.entity.living.*;
import net.neoforged.neoforge.event.tick.EntityTickEvent;
@EventBusSubscriber(modid=KelMagic.MODID)
public final class ArtifactCombat {
    private static final ThreadLocal<Boolean> SHARING=ThreadLocal.withInitial(()->false);
    public static LivingEntity ray(ServerPlayer p,double range,boolean friendly){Vec3 from=p.getEyePosition(),to=from.add(p.getLookAngle().scale(range));var wall=p.serverLevel().clip(new ClipContext(from,to,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,p));double nearest=from.distanceToSqr(wall.getLocation());LivingEntity result=null;for(var e:p.serverLevel().getEntitiesOfClass(LivingEntity.class,new AABB(from,wall.getLocation()).inflate(.5),e->e!=p&&e.isAlive()&&!e.isSpectator())){var at=e.getBoundingBox().inflate(.15).clip(from,wall.getLocation());if(at.isPresent()&&from.distanceToSqr(at.get())<nearest&&(friendly||ArtifactRuntime.canHarm(p,e))){nearest=from.distanceToSqr(at.get());result=e;}}return result;}
    public static boolean magical(Projectile p){return p instanceof ArtifactSpellBolt||p.getType().is(net.minecraft.tags.TagKey.create(Registries.ENTITY_TYPE,ArtifactContent.id("magical_projectiles")))||p.getPersistentData().contains("KelSpellCost");}
    public static boolean parryDamage(ServerPlayer p,DamageSource source){return source.getDirectEntity() instanceof Projectile bolt&&parry(p,bolt);}
    public static boolean parry(ServerPlayer p,Projectile bolt){if(bolt.isRemoved()||!magical(bolt)||!p.isUsingItem()||!p.getUseItem().is(ArtifactContent.SHIELD.get()))return false;Vec3 toward=bolt.position().subtract(p.getEyePosition());if(toward.lengthSqr()<.001)toward=bolt.getDeltaMovement().scale(-1);double dot=p.getLookAngle().dot(toward.normalize());if(!ArtifactRules.parry(p.getTicksUsingItem(),p.getCooldowns().isOnCooldown(ArtifactContent.SHIELD.get()),dot))return false;double refund=ArtifactRules.refund(bolt.getPersistentData().getDouble("KelSpellCost"));bolt.discard();p.stopUsingItem();p.getCooldowns().addCooldown(ArtifactContent.SHIELD.get(),ArtifactRules.PARRY_COOLDOWN);ArtifactRuntime.addMana(p,refund);MagicServer.sync(p);ArtifactVisuals.ring(p.serverLevel(),p.getEyePosition().add(p.getLookAngle().scale(.6)),.6,0x8ef2df,24);ArtifactVisuals.sound(p.serverLevel(),p.position(),"spell_absorb",1.05f);return true;}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public static void impact(ProjectileImpactEvent e){if(e.getProjectile().level().isClientSide)return;if(e.getProjectile().getPersistentData().hasUUID("KelHeldBy")){e.setCanceled(true);return;}if(e.getRayTraceResult() instanceof EntityHitResult hit&&hit.getEntity() instanceof ServerPlayer p&&parry(p,e.getProjectile()))e.setCanceled(true);}
    public static boolean fan(ServerPlayer p){boolean any=false;for(var bolt:p.serverLevel().getEntitiesOfClass(Projectile.class,p.getBoundingBox().inflate(3))){Vec3 delta=bolt.position().subtract(p.getEyePosition());if(delta.lengthSqr()>9||p.getLookAngle().dot(delta.normalize())<.25||!p.hasLineOfSight(bolt)||bolt.getPersistentData().hasUUID("KelHeldBy"))continue;if(!any&&!ArtifactRuntime.spend(p,1))return false;any=true;double speed=Math.max(.8,Math.min(2,bolt.getDeltaMovement().length()));bolt.setOwner(p);bolt.setDeltaMovement(p.getLookAngle().scale(speed));bolt.hasImpulse=true;bolt.hurtMarked=true;ArtifactVisuals.line(p.serverLevel(),p.getEyePosition(),bolt.position(),0xe9cc7e);}if(any)ArtifactVisuals.sound(p.serverLevel(),p.position(),"path_weave",1.4f);return any;}
    public static void holdProjectiles(ServerPlayer p){if(!ArtifactRuntime.canCast(p)){p.stopUsingItem();return;}if(p.tickCount%5==0&&!ArtifactRuntime.spend(p,.15)){p.stopUsingItem();return;}int n=0;for(var bolt:p.serverLevel().getEntitiesOfClass(Projectile.class,p.getBoundingBox().inflate(3))){var t=bolt.getPersistentData();if(t.hasUUID("KelHeldBy")&&!t.getUUID("KelHeldBy").equals(p.getUUID()))continue;if(!t.hasUUID("KelHeldBy")&&(n>=4||bolt.getOwner()==p||!p.hasLineOfSight(bolt)||p.getLookAngle().dot(bolt.position().subtract(p.getEyePosition()).normalize())<.2))continue;if(n++>=4)continue;if(!t.hasUUID("KelHeldBy")){t.putUUID("KelHeldBy",p.getUUID());t.putLong("KelHeldStarted",p.serverLevel().getGameTime());}t.putLong("KelHeldUntil",p.serverLevel().getGameTime()+2);}}
    @SubscribeEvent public static void preTick(EntityTickEvent.Pre e){if(!(e.getEntity() instanceof Projectile bolt)||!(bolt.level() instanceof ServerLevel l))return;var t=bolt.getPersistentData();if(!t.hasUUID("KelHeldBy"))return;var holder=l.getPlayerByUUID(t.getUUID("KelHeldBy"));if(!(holder instanceof ServerPlayer p)||!p.isAlive()||!p.isUsingItem()||!p.getUseItem().is(ArtifactContent.ORB.get())||l.getGameTime()>t.getLong("KelHeldUntil")||l.getGameTime()-t.getLong("KelHeldStarted")>60){bolt.discard();e.setCanceled(true);return;}Vec3 side=p.getLookAngle().cross(new Vec3(0,1,0)).normalize();double offset=((bolt.getId()%4)-1.5)*.3;Vec3 at=p.getEyePosition().add(p.getLookAngle().scale(1.5)).add(side.scale(offset));bolt.setPos(at);bolt.setDeltaMovement(Vec3.ZERO);bolt.hasImpulse=true;bolt.hurtMarked=true;e.setCanceled(true);if(l.getGameTime()%5==0)ArtifactVisuals.ring(l,at,.13,0xb6a5eb,6);}
    public static void root(LivingEntity target,ServerPlayer owner,int duration){if(ArtifactRuntime.immune(target)||!ArtifactRuntime.canHarm(owner,target))return;ArtifactRuntime.state(owner).arrivalUntil=0;var t=target.getPersistentData();t.putLong("KelRootUntil",owner.serverLevel().getGameTime()+duration);t.putString("KelRootDim",target.level().dimension().location().toString());t.putDouble("KelRootX",target.getX());t.putDouble("KelRootY",target.getY());t.putDouble("KelRootZ",target.getZ());target.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN,duration,3),owner);ArtifactVisuals.sound(owner.serverLevel(),target.position(),"root_bind",1);}
    @SubscribeEvent public static void entityTick(EntityTickEvent.Post event){if(event.getEntity() instanceof net.minecraft.world.entity.item.ItemEntity item&&!item.level().isClientSide)ArtifactWorld.recoverSample(item);if(!(event.getEntity() instanceof LivingEntity e)||!(e.level() instanceof ServerLevel l))return;var t=e.getPersistentData();long now=l.getGameTime();if(ArtifactRuntime.immune(e)){t.remove("KelRootUntil");t.remove("KelHeavyUntil");t.remove("KelMuteUntil");}if(t.getLong("KelRootUntil")>now&&t.getString("KelRootDim").equals(l.dimension().location().toString())){Vec3 center=new Vec3(t.getDouble("KelRootX"),t.getDouble("KelRootY"),t.getDouble("KelRootZ"));if(e.position().distanceToSqr(center)>64)t.remove("KelRootUntil");else{e.setDeltaMovement(e.getDeltaMovement().multiply(.1,1,.1));Vec3 delta=e.position().subtract(center);if(delta.horizontalDistanceSqr()>1){Vec3 next=new Vec3(center.x+delta.x/Math.max(1,delta.horizontalDistance()),e.getY(),center.z+delta.z/Math.max(1,delta.horizontalDistance()));if(l.noCollision(e,e.getBoundingBox().move(next.subtract(e.position())))){if(e instanceof ServerPlayer p)p.teleportTo(next.x,next.y,next.z);else e.setPos(next);}}if(now%10==0)ArtifactVisuals.ring(l,e.position().add(0,.1,0),.45,0x77cdb0,10);}}
        if(e instanceof ServerPlayer p){int count=ArtifactRuntime.pieces(p,"steady_anchor");boolean fixed=count==4&&t.getBoolean("KelAnchored")&&p.onGround()&&!p.isPassenger();if(!fixed)t.remove("KelAnchored");attribute(p,Attributes.KNOCKBACK_RESISTANCE,"anchor_stability",count*.18,AttributeModifier.Operation.ADD_VALUE);attribute(p,Attributes.MOVEMENT_SPEED,"anchor_stance",fixed?-.98:0,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);if(fixed){p.setSprinting(false);p.setDeltaMovement(0,p.getDeltaMovement().y,0);Vec3 at=new Vec3(t.getDouble("KelAnchorX"),t.getDouble("KelAnchorY"),t.getDouble("KelAnchorZ"));if(p.position().distanceToSqr(at)<4&&p.position().distanceToSqr(at)>.002&&l.noCollision(p,p.getBoundingBox().move(at.subtract(p.position()))))p.teleportTo(at.x,at.y,at.z);}}
    }
    private static void attribute(ServerPlayer p,net.minecraft.core.Holder<Attribute> type,String name,double amount,AttributeModifier.Operation operation){var attr=p.getAttribute(type);if(attr==null)return;var id=ArtifactContent.id(name);if(amount==0)attr.removeModifier(id);else attr.addOrUpdateTransientModifier(new AttributeModifier(id,amount,operation));}
    public static void rootBarrier(ServerPlayer p){var l=p.serverLevel();for(var dir:net.minecraft.core.Direction.Plane.HORIZONTAL){var pos=p.blockPosition().relative(dir);if(!l.hasChunkAt(pos)||!l.getBlockState(pos).isAir()||!l.mayInteract(p,pos)||!p.getAbilities().mayBuild||!ArtifactWorld.allowed(p,pos)||!l.getWorldBorder().isWithinBounds(pos)||!l.getEntities((Entity)null,new AABB(pos).expandTowards(0,.4,0),x->x instanceof LivingEntity).isEmpty())continue;var snap=net.neoforged.neoforge.common.util.BlockSnapshot.create(l.dimension(),l,pos);l.setBlockAndUpdate(pos,ArtifactContent.ROOT_WALL.get().defaultBlockState());if(net.neoforged.neoforge.event.EventHooks.onBlockPlace(p,snap,net.minecraft.core.Direction.UP)){snap.restore();continue;}if(l.getBlockEntity(pos) instanceof ArtifactBlockEntity be){be.owner=p.getUUID();be.expires=l.getGameTime()+60;be.changed();l.scheduleTick(pos,ArtifactContent.ROOT_WALL.get(),60);}}ArtifactVisuals.ring(l,p.position().add(0,.2,0),1.2,0x82e0bd,24);}
    @SubscribeEvent public static void jump(LivingEvent.LivingJumpEvent e){var l=e.getEntity();if(l.level().isClientSide)return;var t=l.getPersistentData();if(t.getLong("KelHeavyUntil")>l.level().getGameTime()||t.getLong("KelRootUntil")>l.level().getGameTime()||l instanceof ServerPlayer p&&ArtifactRuntime.pieces(p,"steady_anchor")==4&&t.getBoolean("KelAnchored")){l.setDeltaMovement(l.getDeltaMovement().multiply(1,0,1));l.hurtMarked=true;}}
    @SubscribeEvent public static void vibration(VanillaGameEvent e){if(ArtifactRuntime.silent(e.getCause()))e.setCanceled(true);}
    public static void shareDamage(LivingIncomingDamageEvent e){if(SHARING.get()||!(e.getEntity().level() instanceof ServerLevel l)||e.getSource().is(ResourceKey.create(Registries.DAMAGE_TYPE,ArtifactContent.id("mana_debt")))||e.getSource().is(ResourceKey.create(Registries.DAMAGE_TYPE,ArtifactContent.id("oath_debt"))))return;for(var donor:l.players()){var tag=donor.getPersistentData();if(donor==e.getEntity()||!donor.isAlive()||!donor.getMainHandItem().is(ArtifactContent.OATH.get())||!tag.hasUUID("KelOathTarget")||!tag.getUUID("KelOathTarget").equals(e.getEntity().getUUID())||tag.getLong("KelOathUntil")<=l.getGameTime()||donor.distanceToSqr(e.getEntity())>144||!donor.hasLineOfSight(e.getEntity())||!donor.isAlliedTo(e.getEntity()))continue;float amount=e.getAmount()*.3f;var key=ResourceKey.<DamageType>create(Registries.DAMAGE_TYPE,ArtifactContent.id("oath_debt"));SHARING.set(true);try{if(donor.hurt(new DamageSource(l.registryAccess().registryOrThrow(Registries.DAMAGE_TYPE).getHolderOrThrow(key)),amount)){e.setAmount(e.getAmount()-amount);ArtifactVisuals.line(l,donor.position().add(0,1,0),e.getEntity().position().add(0,1,0),0xe1bf72);}}finally{SHARING.set(false);}break;}}
    public static SpellEffects.Aim markedAim(ServerPlayer p){if(!p.getMainHandItem().is(ArtifactContent.RAPIER.get())||p.getPersistentData().getLong("KelRapierUntil")<=p.serverLevel().getGameTime())return null;for(var e:p.serverLevel().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(ArtifactRuntime.range(p)),e->e.isAlive()&&e.getPersistentData().hasUUID("KelRapierOwner")&&e.getPersistentData().getUUID("KelRapierOwner").equals(p.getUUID())&&e.getPersistentData().getLong("KelRapierMark")>p.serverLevel().getGameTime()))if(p.hasLineOfSight(e)&&p.getLookAngle().dot(e.getEyePosition().subtract(p.getEyePosition()).normalize())>.65){var hit=p.serverLevel().clip(new ClipContext(p.getEyePosition(),e.getEyePosition(),ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,p));return new SpellEffects.Aim(e.position(),HitResult.Type.ENTITY,hit,e);}return null;}
    private ArtifactCombat(){}
}
